{
  "titre": "Rituel mathématiques : tables de multiplication",
  "objectifGeneral": "Réactiver rapidement la maîtrise des tables de multiplication",
  "notionsPivots": [
    "les tables de multiplication",
    "les facteurs multiplicatifs",
    "le produit",
    "la mémorisation",
    "la rapidité d'exécution"
  ],
  "etapes": [
    {
      "titre": "Vérification rapide",
      "objectif": "repérer ses connaissances immédiates",
      "cartes": [
        {
          "titre": "Évaluation ciblée",
          "objectif": "valider une affirmation simple",
          "module": "TrueFalse",
          "palier": "entrainement",
          "duree": 2,
          "consigne": "Répondre à une question Vrai/Faux sur une table de multiplication en moins de 30 secondes. L'enseignant note les réponses pour cibler les lacunes."
        }
      ]
    },
    {
      "titre": "Compléter les calculs",
      "objectif": "restituer les résultats manquants",
      "cartes": [
        {
          "titre": "Remplir les blancs",
          "objectif": "inscrire les nombres dans les cases",
          "module": "FillInTheBlanks",
          "palier": "entrainement",
          "duree": 4,
          "consigne": "Compléter 5 calculs de multiplication à trous (ex: 7 x ___ = 42) au clavier, en 1 minute chrono. L'enseignant observe les stratégies utilisées."
        }
      ]
    },
    {
      "titre": "Choisir le bon résultat",
      "objectif": "sélectionner le produit correct",
      "cartes": [
        {
          "titre": "Quiz rapide",
          "objectif": "cocher la réponse appropriée",
          "module": "SingleChoiceSet",
          "palier": "entrainement",
          "duree": 4,
          "consigne": "Parmi 4 propositions, sélectionner le résultat exact d'un calcul de multiplication en 15 secondes par question. L'enseignant corrige collectivement."
        }
      ]
    }
  ]
}
